using System.Collections.Generic;
using DestructionRacing.Tools;
using Godot;

namespace DestructionRacing.Tracks;

/// <summary>The Bowl's three lighting presets (plan §7.3).</summary>
public enum BowlPreset { Afternoon, GoldenHour, Night }

/// <summary>
/// The Bowl as the derby venue (M4): the baked look of one lighting preset (generated by BowlLookBuilder.gd),
/// collision that matches the tyre barrier, the crowd, the live scoreboard and the floodlight flare for the
/// final cars. Headless runs build the collision only, so sims behave exactly like the visual game.
/// </summary>
public partial class Bowl : Node3D
{
    /// <summary>Semi-axes of the floor's edge ellipse (the foot of the concrete wall).</summary>
    public const float SemiAxisX = 55f, SemiAxisZ = 38f;
    /// <summary>The tyre barrier reaches this far inside the floor's edge; its face is where cars hit.</summary>
    public static float BarrierInset { get; set; } = 0.83f;
    /// <summary>Experiments (--greywalls): the M1–M3 grey-box wall (1 m thick, 1.6 m high, face 0.5 m in).</summary>
    public static bool GreyWalls { get; set; }
    private const int Segments = 96;

    public BowlPreset Preset { get; set; } = BowlPreset.Afternoon;
    public bool Visuals { get; set; } = true;

    public Crowd? Crowd { get; private set; }
    /// <summary>The dirt floor of the look scene (for the ground marks); null headless.</summary>
    public MeshInstance3D? Floor { get; private set; }
    public bool IsNight => Preset == BowlPreset.Night;
    /// <summary>The floodlights are on (golden hour and night).</summary>
    public bool FloodlightsOn => Preset != BowlPreset.Afternoon;

    private Label3D? _scoreInfo;
    private readonly List<(SpotLight3D Light, float Energy)> _floods = new();
    private float _flare;

    public static string ScenePath(BowlPreset preset) => preset switch
    {
        BowlPreset.GoldenHour => "res://scenes/bowl/BowlLook_Golden.tscn",
        BowlPreset.Night => "res://scenes/bowl/BowlLook_Night.tscn",
        _ => "res://scenes/bowl/BowlLook.tscn",
    };

    public static BowlPreset Parse(string? name) => name?.ToLowerInvariant() switch
    {
        "golden" or "goldenhour" or "golden_hour" or "dusk" => BowlPreset.GoldenHour,
        "night" => BowlPreset.Night,
        _ => BowlPreset.Afternoon,
    };

    public static string DisplayName(BowlPreset preset) => preset switch
    {
        BowlPreset.GoldenHour => "Golden hour",
        BowlPreset.Night => "Night",
        _ => "Afternoon",
    };

    public override void _Ready()
    {
        BuildCollision();
        if (!Visuals) return;
        var look = GD.Load<PackedScene>(ScenePath(Preset)).Instantiate<BowlLook>();
        look.Empty = true;
        AddChild(look);
        _scoreInfo = look.GetNodeOrNull<Label3D>("Scoreboard/Info");
        Floor = look.GetNodeOrNull<MeshInstance3D>("Floor");
        foreach (var node in look.FindChildren("Flood", nameof(SpotLight3D), true, false))
            if (node is SpotLight3D spot) _floods.Add((spot, spot.LightEnergy));
        Crowd = new Crowd { Night = IsNight };
        AddChild(Crowd);
    }

    /// <summary>A point on the floor's edge ellipse, pushed <paramref name="offset"/> metres outward along its normal.</summary>
    public static Vector3 Ellipse(float t, float offset)
    {
        var p = new Vector3(SemiAxisX * Mathf.Cos(t), 0f, SemiAxisZ * Mathf.Sin(t));
        var n = new Vector3(Mathf.Cos(t) / SemiAxisX, 0f, Mathf.Sin(t) / SemiAxisZ).Normalized();
        return p + n * offset;
    }

    /// <summary>
    /// The floor (an infinite plane at y = 0) and the perimeter: per segment a solid block from the tyre
    /// barrier's face back to the rear of the wall, 1.45 m high, and the catch fence above it up to 4.1 m.
    /// </summary>
    private void BuildCollision()
    {
        var ground = new StaticBody3D { Name = "GroundBody" };
        ground.AddChild(new CollisionShape3D { Shape = new WorldBoundaryShape3D() });
        AddChild(ground);

        var walls = new StaticBody3D { Name = "Perimeter" };
        walls.SetMeta("surface", "tyres");
        AddChild(walls);
        for (int i = 0; i < Segments; i++)
        {
            float t0 = Mathf.Tau * i / Segments, t1 = Mathf.Tau * (i + 1) / Segments, tm = (t0 + t1) * 0.5f;
            if (GreyWalls)
            {
                AddBlock(walls, t0, t1, tm, -0.5f, 0.5f, 0f, 1.6f);
                continue;
            }
            AddBlock(walls, t0, t1, tm, -BarrierInset, 0.7f, 0f, 1.45f);
            AddBlock(walls, t0, t1, tm, 0.40f, 0.56f, 1.45f, 4.1f);
        }
    }

    private static void AddBlock(StaticBody3D body, float t0, float t1, float tm, float inner, float outer, float y0, float y1)
    {
        Vector3 a = Ellipse(t0, inner), b = Ellipse(t1, inner);
        var normal = (Ellipse(tm, 1f) - Ellipse(tm, 0f)).Normalized();
        var along = (b - a).Normalized();
        float thickness = outer - inner;
        var centre = (a + b) * 0.5f + normal * (thickness * 0.5f) + Vector3.Up * ((y0 + y1) * 0.5f);
        var basis = new Basis(normal, Vector3.Up, -along).Orthonormalized();
        if (basis.Determinant() < 0f) basis = new Basis(normal, Vector3.Up, along).Orthonormalized();
        body.AddChild(new CollisionShape3D
        {
            Shape = new BoxShape3D { Size = new Vector3(thickness, y1 - y0, a.DistanceTo(b) + 0.06f) },
            Transform = new Transform3D(basis, centre),
        });
    }

    /// <summary>The second line of the scoreboard (e.g. "CARS LEFT 12").</summary>
    public void SetScoreboard(string text)
    {
        if (_scoreInfo != null && _scoreInfo.Text != text) _scoreInfo.Text = text;
    }

    /// <summary>The floodlights flare up for a moment (the final 5/3/2 cars, plan §11).</summary>
    public void Flare() => _flare = 1f;

    public override void _Process(double delta)
    {
        if (_flare <= 0f || _floods.Count == 0) return;
        _flare = Mathf.Max(0f, _flare - (float)delta * 0.8f);
        float k = 1f + 1.2f * _flare * _flare;
        foreach (var (light, energy) in _floods) light.LightEnergy = energy * k;
    }
}
